import {clone,validateGraph,type EditDef} from '../model';
import {example} from '../examples';
import {serialize} from '../serialize';
import {catalog,createBlock,addBlock,arrange,describeNode,linearSteps,placeholderBindings,freshEdit,validateDraft,importDraft,removeBlock,duplicateBlock} from '../authoring';
import {NodeCanvas,esc} from './canvas';
import {renderSettings} from './settings';
import {PipelineHistory} from '../history';
import {definitionGraph,graphDefinition,workflowBlock,updateStep} from '../workflows';
import {connect,connectionBetween,insertConnected as insertNative,type Pin} from '../authoring';
import {workflowSettings} from './workflow-settings';
import {type Definition,type Step,copy,currentDefinitions,cloneDefinition,walkSteps} from '../../model';
export interface EditMenuHooks {edits:()=>EditDef[];save:(edit:EditDef)=>void;legacy:()=>{id:string;name:string;kind:string}[];openLegacy:(id:string)=>HTMLDialogElement;dialog:(title:string,body:string,wide?:boolean)=>HTMLDialogElement;message:(text:string,error?:boolean)=>void;initial?:EditDef;definitions?:()=>Definition[];saveDefinition?:(d:Definition)=>void;confirm?:(body:string)=>Promise<'keep'|'unlock'|'clone'>;sharing?:(count:number)=>Promise<'everywhere'|'copy'|'cancel'>;run?:(edit:EditDef)=>Promise<void>}
export function openEditMenu(h:EditMenuHooks){
  const d=h.dialog('Edit workspace','',true);d.classList.add('node-editor-dialog');d.querySelector('.dialog-actions')!.remove();const body=d.querySelector<HTMLElement>('.dialog-body')!;
  const library=h.definitions?.()??[],first=currentDefinitions(library)[0],initial=h.initial??h.edits()[0]??(first?definitionGraph(first,library):definitionGraph({id:crypto.randomUUID(),version:1,kind:'quick',name:'My first Edit',description:'',mode:'suggested',initial:false,steps:[]}));
  let current=clone(initial),history=new PipelineHistory(current),selected:string|null=null,listMode=false,libraryTab=current.workflow?.kind==='preset'?'presets':'edits',dirty=false;
  body.innerHTML=`<div class="node-edit-shell"><aside class="node-library"><div class="node-library-heading">AUTOMATION</div><nav class="node-library-tabs" aria-label="Edit library"><button data-library="edits" class="active">Edits</button><button data-library="recipes">Recipes</button><button data-library="presets">Presets</button></nav><div id="node-library-items"></div><div class="node-library-bottom"><button data-command="new">+ New Edit</button><button data-command="new-preset">+ New preset</button><button data-command="new-signals">+ Signal pipeline</button><button data-command="import">Import JSON</button><input type="file" id="node-import" accept=".json,application/json" hidden></div></aside><section class="node-workspace"><div class="node-editor-toolbar"><label class="node-edit-name"><span class="sr-only">Edit name</span><input id="node-edit-name" value="${esc(current.name)}" maxlength="100"></label><button data-command="undo" title="Undo (Ctrl+Z)">↶</button><button data-command="redo" title="Redo (Ctrl+Shift+Z)">↷</button><div class="node-view-toggle"><button data-command="graph" aria-pressed="true">Nodes</button><button data-command="list" aria-pressed="false">List</button></div><button data-command="run" class="primary">Run</button><button data-command="clone">Clone</button><button data-command="validate">Check</button><button data-command="export">Export JSON</button></div><div id="node-workflow-controls" class="node-workflow-controls"></div><div id="node-shelf" class="node-shelf"></div><div class="node-addbar"><button data-command="search" title="Right-click the canvas or press Space">Add node…</button><span class="node-addbar-spacer"></span><button data-command="arrange">Arrange</button><button data-command="zoom-out" aria-label="Zoom out">−</button><button data-command="fit">Fit</button><button data-command="zoom-in" aria-label="Zoom in">+</button></div><div class="node-canvas" id="node-canvas"></div><div class="node-list hidden" id="node-list" aria-label="Read-only workflow list"></div><div class="node-editor-status" role="status" aria-live="polite" id="node-editor-status">Add nodes, then drag or click an output and an input to connect them.</div><div class="node-phase-note">Drag a grouped node above onto the canvas. Select a node to adjust its channel and settings.</div></section><aside class="node-settings" id="node-settings"></aside></div>`;
  const $=<T extends HTMLElement=HTMLElement>(s:string)=>body.querySelector<T>(s)!;
  const message=(text:string)=>{$('#node-editor-status').textContent=text;};
  function items():readonly (readonly [string,string,string])[]{if(!current.workflow)return catalog;const reuse=(h.definitions?currentDefinitions(h.definitions()):[]).filter(d=>d.id!==current.id).map(d=>[`reuse:${d.id}`,d.kind==='preset'?'Presets':'Edits',d.name] as const);return current.workflow.kind==='preset'?[['source','Media','Media'],...reuse,['workflow-decide','Decide','Decide']]:[['source','Media','Media'],['workflow-detectQuiet','Signal','Quiet signal'],['workflow-decide','Decide','Decide'],['workflow-action','Action','Action'],...reuse];}
  function insert(kind:string,id:string,x:number,y:number,pin?:Pin){if(!current.workflow)return insertNative(current,kind,id,x,y,pin);const n=kind==='source'?createBlock(kind,id):workflowBlock(kind,id);n.ui={x:Math.max(0,Math.round(x/16)*16),y:Math.max(0,Math.round(y/16)*16)};if(kind.startsWith('reuse:'))n.name=h.legacy().find(d=>d.id===kind.slice(6))?.name??'Edit';let next=addBlock(current,n);if(pin){let error='No compatible input.';for(const p of pin.direction==='out'?n.inputs:n.outputs)try{return connect(next,connectionBetween(pin,{node:id,port:p.id,direction:pin.direction==='out'?'in':'out'}));}catch(e){error=(e as Error).message;}throw Error(error);}return next;}
  const canvas=new NodeCanvas($('#node-canvas'),{change:next=>change(next),select:id=>{selected=id;showSettings();},message,items,insert});
  function showSettings(){const host=$('#node-settings');host.onchange=null;host.onclick=null;const n=current.nodes.find(n=>n.id===selected);if(!n&&current.workflow){rootSettings();return;}if(n?.params.legacyStep){workflowSettings($('#node-settings'),n.params.legacyStep as Step,step=>change(updateStep(current,n.id,step)),{library:()=>h.definitions?.()??[],saveDefinition:d=>h.saveDefinition?.(d),source:id=>loadDefinition(id),confirm:body=>h.confirm?.(body)??Promise.resolve('keep'),branch:which=>{const step=copy(n.params.legacyStep as Step);if(step.type!=='condition')return;const branchDef:Definition={id:`${current.id}/${n.id}/${which}`,version:1,kind:'quick',name:`${current.name} · ${which==='then'?'Then':'Otherwise'}`,description:'Conditional branch',initial:false,mode:'inherit',steps:step[which]};const initial=(n.params.branchDrafts as Record<string,EditDef>|undefined)?.[which]??definitionGraph(branchDef,h.definitions?.());openEditMenu({...h,initial,sharing:undefined,save:g=>{const next=clone(current),node=next.nodes.find(node=>node.id===n.id)!;node.params.branchDrafts={...(node.params.branchDrafts as object??{}),[which]:g};try{(node.params.legacyStep as typeof step)[which]=graphDefinition(g).steps;}catch{}change(next);}}); }},message);nodeAlias(n.id,n.name);}else renderSettings($('#node-settings'),current,selected,change,message);}
  let sharingChecked=false,sharingPending=false;
  function nodeAlias(id:string,name:string){const field=document.createElement('label'),input=document.createElement('input');field.className='node-field';field.append(document.createTextNode('Node name'));input.value=name;input.dataset.nodeAlias='true';input.onchange=()=>{const next=clone(current);next.nodes.find(n=>n.id===id)!.name=input.value.trim()||name;change(next);};field.append(input);$('#node-settings').prepend(field);}
  function uses(){return currentDefinitions(h.definitions?.()??[]).reduce((count,d)=>count+walkSteps(d.steps).filter(s=>s.type==='reference'&&s.definitionId===current.id).length,0);}
  function requiresSharing(){if(!current.workflow||!uses())return false;try{const d=graphDefinition(current),old=currentDefinitions(h.definitions?.()??[]).find(v=>v.id===current.id);return !!old&&JSON.stringify({...old,version:0})!==JSON.stringify({...d,version:0});}catch{return false;}}
  function rootSettings(){const host=$('#node-settings'),versions=(h.definitions?.()??[]).filter(d=>d.id===current.id).sort((a,b)=>b.version-a.version);host.innerHTML=`<h3>${current.workflow!.kind==='preset'?'Preset':'Edit'} settings</h3><p class="node-setting-note">Used in ${uses()} places. Linked uses follow updates; frozen uses retain their settings.</p><label class="node-field"><span>Description</span><textarea id="edit-description">${esc(current.workflow!.description)}</textarea></label><label class="node-field"><span>Saved versions</span><select id="edit-history">${versions.map(d=>`<option value="${d.version}">Version ${d.version}</option>`).join('')}</select></label><button id="restore-version">Restore as current settings</button>`;$<HTMLTextAreaElement>('#edit-description').onchange=e=>{const next=clone(current);next.workflow!.description=(e.target as HTMLTextAreaElement).value;change(next);};$('#restore-version').onclick=()=>{const version=versions.find(v=>v.version===Number($<HTMLSelectElement>('#edit-history').value));if(version)change(definitionGraph(version,h.definitions?.()));};}
  function persist(){if(requiresSharing()&&h.sharing&&!sharingChecked){if(!sharingPending){sharingPending=true;void h.sharing(uses()).then(answer=>{sharingPending=false;if(answer==='cancel'){current=history.undo();dirty=false;render();return;}if(answer==='copy'){const d=cloneDefinition(graphDefinition(current),h.definitions?.()??[],`${current.name} copy`);current=definitionGraph(d,h.definitions?.());history=new PipelineHistory(current);}sharingChecked=true;persist();render();}).catch(e=>{sharingPending=false;message(e.message);});}return false;}h.save(clone(current));dirty=false;return true;}
  function change(next:EditDef){try{validateDraft(next);if(JSON.stringify(next)===JSON.stringify(current))return;if(next.nodes.length>current.nodes.length)selected=next.nodes.at(-1)!.id;current=history.commit(next);dirty=true;const saved=persist();render();message(saved?'Saved draft. Drag another pin to connect the next step.':'Choose how to update this shared Edit.');}catch(e){message((e as Error).message);}}
  function load(edit:EditDef){current=clone(edit);history=new PipelineHistory(current);selected=null;dirty=false;sharingChecked=false;render();canvas.fit();}
  function loadDefinition(id:string){const definition=currentDefinitions(h.definitions?.()??[]).find(d=>d.id===id);if(definition)load(h.edits().find(edit=>edit.id===id)??definitionGraph(definition,h.definitions?.()));else h.openLegacy(id);}
  function renderDock(){const dock=$('#node-shelf');dock.innerHTML= [...new Set(items().map(c=>c[1]))].map(group=>`<section><span>${esc(group.toUpperCase())}</span><div>${items().filter(c=>c[1]===group).map(([kind,,label])=>`<button draggable="true" data-shelf="${esc(kind)}" title="Drag to the canvas">${esc(label)}</button>`).join('')}</div></section>`).join('');dock.querySelectorAll<HTMLButtonElement>('[data-shelf]').forEach(button=>{button.ondragstart=e=>{e.dataTransfer!.setData('application/x-cutline-node',button.dataset.shelf!);e.dataTransfer!.effectAllowed='copy';};button.onclick=e=>{e.stopPropagation();if(listMode)command('graph');canvas.addAtCenter(button.dataset.shelf!);};});const controls=$('#node-workflow-controls');controls.innerHTML=current.workflow?`<span>${current.workflow.kind==='preset'?'PRESET · CHAIN EDITS':'EDIT · DEFINE ACTIONS'}</span><select id="workflow-mode" aria-label="Default implementation">${[['inherit','Use node settings'],['automatic','Automatic'],['suggested','Suggest on timeline']].map(([v,l])=>`<option value="${v}"${current.workflow!.mode===v?' selected':''}>${l}</option>`).join('')}</select><label><input type="checkbox" id="workflow-initial"${current.workflow.initial?' checked':''}> Offer when adding media</label>`:'<span>SIGNAL PIPELINE · MEASURE → TRACK → DECIDE → SELECT</span>';const mode=$<HTMLSelectElement>('#workflow-mode'),initial=$<HTMLInputElement>('#workflow-initial');if(mode)mode.onchange=()=>{const next=clone(current);next.workflow!.mode=mode.value as 'inherit';change(next);};if(initial)initial.onchange=()=>{const next=clone(current);next.workflow!.initial=initial.checked;change(next);};}
  function renderPalette(node:HTMLElement){node.innerHTML='<input class="blueprint-palette-search" type="search" placeholder="Search nodes…" aria-label="Search node palette"><p class="node-library-note">Drag a node onto the grid, or click to add it at the center.</p><div class="blueprint-palette-items"></div>';const input=node.querySelector('input')!,paletteList=node.querySelector<HTMLElement>('.blueprint-palette-items')!;const update=()=>{paletteList.replaceChildren();let prior='';for(const [kind,group,label]of items().filter(c=>`${c[1]} ${c[2]}`.toLowerCase().includes(input.value.toLowerCase()))){if(group!==prior){const heading=document.createElement('div');heading.className='node-library-subtitle';heading.textContent=group;paletteList.append(heading);prior=group;}const button=document.createElement('button');button.className='blueprint-palette-card';button.draggable=true;button.innerHTML=`<span class="palette-grip">⠿</span><span>${esc(label)}</span>`;button.ondragstart=e=>{e.dataTransfer!.setData('application/x-cutline-node',kind);e.dataTransfer!.effectAllowed='copy';};button.ondragend=()=>$('#node-canvas').classList.remove('palette-drop-target');button.onclick=()=>{if(listMode)command('graph');canvas.addAtCenter(kind);};paletteList.append(button);}};input.oninput=update;update();}
  function renderLibrary(){body.querySelectorAll<HTMLElement>('[data-library]').forEach(b=>b.classList.toggle('active',b.dataset.library===libraryTab));const node=$('#node-library-items');if(libraryTab==='recipes'){node.innerHTML=`<p class="node-library-note">Start with a signal graph. Analyze media, then mark selected regions to run timeline Edits.</p>${[['remove','Remove long silences','Find quiet → select → remove'],['cross','Cross-revision tagging','Remove → tag surviving content']].map(([id,name,description])=>`<button class="node-recipe" data-recipe="${id}"><strong>${name}</strong><span>${description}</span><small>SIGNAL ANALYSIS</small></button>`).join('')}`;}else{node.innerHTML=`${h.edits().filter(edit=>!h.legacy().some(d=>d.id===edit.id)).filter(edit=>libraryTab==='presets'?edit.workflow?.kind==='preset':edit.workflow?.kind!=='preset').map(edit=>`<button class="node-library-item${edit.id===current.id?' active':''}" data-load-edit="${esc(edit.id)}"><strong>${esc(edit.name)}</strong><small>${edit.nodes.length} nodes · v${edit.version}</small></button>`).join('')||'<p class="node-library-note">Create an Edit or choose a recipe to start.</p>'}<div class="node-library-subtitle">REUSABLE PIPELINES</div>${h.legacy().filter(edit=>libraryTab==='presets'?edit.kind==='preset':edit.kind==='quick').map(edit=>`<button class="node-library-item node-legacy" data-legacy-edit="${esc(edit.id)}"><strong>${esc(edit.name)}</strong><small>${edit.kind==='quick'?'Edit':'Preset'} · open pipeline</small></button>`).join('')}`;}}
  function renderList(){try{$('#node-list').innerHTML=`<p class="node-list-note">Read-only view · connections determine execution order.</p><ol>${linearSteps(current).map(step=>`<li><strong>${esc(step.name)}</strong><p>${esc(step.description)}</p><small>${step.inputs.length?`Receives: ${esc(step.inputs.join(', '))}`:'Starts here'}</small></li>`).join('')}</ol>`;}catch(e){$('#node-list').textContent=(e as Error).message;}}
  function render(){canvas.set(current,selected);showSettings();renderDock();$<HTMLInputElement>('#node-edit-name').value=current.name;renderLibrary();renderList();const run=body.querySelector<HTMLButtonElement>('[data-command=run]')!;run.textContent=current.workflow?'Run':'Analyze';}
  function download(){const blob=new Blob([serialize(current)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${current.name.replace(/[<>:"/\\|?*]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  let zoom=1;
  function command(name:string){
    if(name==='new'||name==='new-preset'){const d:Definition={id:crypto.randomUUID(),version:1,name:name==='new'?'New Edit':'New preset',kind:name==='new'?'quick':'preset',description:'',mode:'suggested',initial:false,steps:[]};const edit=definitionGraph(d,h.definitions?.());h.save(edit);load(edit);}
    if(name==='new-signals'){const edit=freshEdit(crypto.randomUUID(),'Signal pipeline');h.save(edit);load(edit);}
    if(name==='clone'){const definition=current.workflow?cloneDefinition(graphDefinition(current),h.definitions?.()??[],`${current.name} copy`):undefined;const edit=definition?definitionGraph(definition,h.definitions?.()):{...clone(current),id:crypto.randomUUID(),name:`${current.name} copy`,version:1,derivedFrom:{editId:current.id,version:current.version}};if(definition)h.saveDefinition?.(definition);h.save(edit);load(edit);}
    if(name==='run'){const button=body.querySelector<HTMLButtonElement>('[data-command=run]')!;button.disabled=true;button.textContent='Working…';void h.run?.(clone(current)).catch(e=>message(e.message)).finally(()=>{button.disabled=false;button.textContent=current.workflow?'Run':'Analyze';});}
    if(name==='search'){if(listMode)command('graph');canvas.openSearch();}
    if(name==='undo'||name==='redo'){const next=name==='undo'?history.undo():history.redo();current=clone(next);persist();render();message(name==='undo'?'Undid the last graph change.':'Redid the graph change.');}
    if(name==='arrange'){change(arrange(current));zoom=canvas.fit();}
    if(name==='fit')zoom=canvas.fit();if(name==='zoom-in')zoom=canvas.setZoom(canvas.scale+.1);if(name==='zoom-out')zoom=canvas.setZoom(canvas.scale-.1);
    if(name==='graph'||name==='list'){listMode=name==='list';$('#node-canvas').classList.toggle('hidden',listMode);$('#node-list').classList.toggle('hidden',!listMode);body.querySelector('[data-command="graph"]')!.setAttribute('aria-pressed',String(!listMode));body.querySelector('[data-command="list"]')!.setAttribute('aria-pressed',String(listMode));renderList();}
    if(name==='validate'){try{if(current.workflow)graphDefinition(current);else validateGraph(current,placeholderBindings(current));message(current.nodes.length?'Connections are valid. Run uses the current connected settings.':'Add a Media input and connect some steps.');}catch(e){message((e as Error).message);}}
    if(name==='export')download();if(name==='import')$<HTMLInputElement>('#node-import').click();
  }
  body.addEventListener('click',e=>{const target=(e.target as Element).closest<HTMLElement>('button');if(!target)return;try{if(target.dataset.command)command(target.dataset.command);if(target.dataset.library){libraryTab=target.dataset.library;body.querySelectorAll<HTMLElement>('[data-library]').forEach(b=>b.classList.toggle('active',b.dataset.library===libraryTab));renderLibrary();}if(target.dataset.loadEdit){const edit=h.edits().find(edit=>edit.id===target.dataset.loadEdit);if(edit)load(edit);}if(target.dataset.recipe){const edit=arrange(example(target.dataset.recipe as 'remove'));edit.id=crypto.randomUUID();edit.name+=' copy';h.save(edit);load(edit);message('Recipe copied. Analyze your media to see signals and selected regions.');}if(target.dataset.legacyEdit)loadDefinition(target.dataset.legacyEdit);}catch(error){message((error as Error).message);}});
  $<HTMLInputElement>('#node-edit-name').onchange=e=>{const name=(e.target as HTMLInputElement).value.trim();if(name)change({...clone(current),name});else message('Give this Edit a name.');};
  $<HTMLInputElement>('#node-import').onchange=e=>{void(async()=>{const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Choose a graph JSON file smaller than 5 MB.');const edit=importDraft(await file.text());edit.id=crypto.randomUUID();edit.name+=' (imported)';h.save(edit);load(edit);message('Imported as an independent Edit. The original saved Edit is unchanged.');}catch(error){message((error as Error).message);}finally{input.value='';}})();};
  d.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!(e.target as Element).closest('input,textarea,select')){e.preventDefault();command(e.shiftKey?'redo':'undo');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();message('Saved in this project. Use File → Save project for a project JSON backup.');}});
  d.addEventListener('close',()=>{canvas.dispose();if(dirty)persist();},{once:true});render();requestAnimationFrame(()=>{zoom=canvas.fit();});return d;
}
