import {duration,sourceAt,type Clip,type Project} from './model';
import {audioGain} from './render';
import type {Media} from './media';
import type {TimeScale} from './storyboard';
import {regionBounds} from './markers';
export type AudioView='waveform'|'levels'|'frequency'|'none';
export type VideoView='filmstrip'|'plain';
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const short=(t:number)=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
interface Options {project:Project;selected:string|null;playhead:number;structure:boolean;scale:TimeScale;zoom:number;audioView:AudioView;videoView:VideoView;media:Media;icon:(name:string)=>string;}
export function renderTracks(host:HTMLElement,scroller:HTMLElement,o:Options){
  const {project:p,scale,media,icon}=o,visible=scroller.clientWidth||1000,left=Math.max(0,scroller.scrollLeft-220),right=scroller.scrollLeft+visible+220,width=Math.max(visible-120,scale.width+100),ticks:string[]=[];
  const rowEnds:number[]=[];
  const regions=(p.regions??[]).flatMap(r=>{const bounds=regionBounds(p,r);return bounds?[{...r,start:bounds[0],end:bounds[1]}]:[];}).sort((a,b)=>a.start-b.start).map(r=>{let row=rowEnds.findIndex(end=>end<scale.toX(r.start)-4);if(row<0)row=rowEnds.length;rowEnds[row]=Math.max(scale.toX(r.end),scale.toX(r.start)+8);return {...r,row};});
  const times=o.structure?scale.times:(()=>{const interval=[.5,1,2,5,10,15,30,60,120,300,600,900,1800].find(i=>i*o.zoom>=65)??1800;const values=[];for(let t=Math.max(0,Math.floor(scale.toTime(left)/interval)*interval);t<=scale.toTime(right)+interval;t+=interval)values.push(t);return values;})();
  let last=-1e6;for(const t of times){const x=scale.toX(t);if(x<left||x>right)continue;const label=x-last>=62;if(label)last=x;ticks.push(`<div class="ruler-tick${o.structure?' structural':''}" style="left:${x}px" title="${t.toFixed(3)} seconds">${label?`<span>${short(t)}</span>`:''}</div>`);}
  host.style.width=`${width+120}px`;host.classList.toggle('structure-view',o.structure);
  host.innerHTML=`<div class="ruler${regions.length?' has-regions':''}" data-ruler style="height:${30+rowEnds.length*22}px">${ticks.join('')}${regions.map(r=>`<button class="marked-region" data-region="${esc(r.id)}" style="left:${scale.toX(r.start)}px;width:${Math.max(8,scale.toX(r.end)-scale.toX(r.start))}px;top:${30+r.row*22}px;--region-color:${/^#[0-9a-f]{6}$/i.test(r.color)?r.color:'#efc17b'}" title="${esc(r.name)} · ${r.start.toFixed(2)}–${r.end.toFixed(2)}s · click to edit or run a workflow" aria-label="Edit marked region ${esc(r.name)}"><span>${esc(r.name)}</span></button>`).join('')}${p.markers.map(m=>`<button class="marker-flag" data-marker="${esc(m.id)}" title="${esc(m.name)} · drag to move · Shift-drag to mark a region" aria-label="Edit marker ${esc(m.name)}" style="left:${scale.toX(m.time)}px;--marker-color:${/^#[0-9a-f]{6}$/i.test(m.color??'')?m.color:'#efc17b'}">${icon('marker')}<span>${esc(m.name)}</span></button>`).join('')}</div>${[...p.tracks].reverse().map(t=>`<div class="track-row"><div class="track-label">${icon(t.kind==='audio'?'audio':'video')}<span>${esc(t.name)}</span><button class="icon ghost${t.muted?' muted-track':''}" data-mute="${esc(t.id)}" title="Toggle track">${icon(t.muted?'mute':'sound')}</button></div><div class="track-lane" data-lane="${esc(t.id)}">${o.structure?scale.positions.filter(x=>x>=left&&x<=right).map(x=>`<span class="structure-boundary" style="left:${x}px"></span>`).join(''):''}${p.clips.filter(c=>c.trackId===t.id&&scale.toX(c.start+duration(c))>=left&&scale.toX(c.start)<=right).map(c=>{
      const x=scale.toX(c.start),end=scale.toX(c.start+duration(c)),visualLeft=Math.max(0,left-x),visualWidth=Math.max(1,Math.min(end,right)-Math.max(x,left));
      return `<div class="clip ${t.kind}${c.id===o.selected?' selected':''}${c.enabled?'':' disabled'}" data-clip="${esc(c.id)}" style="left:${x}px;width:${Math.max(3,end-x)}px" title="${esc(c.name)} · ${duration(c).toFixed(2)}s"><span class="clip-edge left" data-edge="left"></span><span class="clip-name" style="left:${visualLeft}px">${esc(c.name)}</span><span class="clip-sub" style="left:${visualLeft}px">${c.rate!==1?`${c.rate.toFixed(2)}× · `:''}${short(duration(c))}${c.quiet?' · matching':''}</span><canvas data-visual="${esc(c.id)}" data-x="${x+visualLeft}" style="left:${visualLeft}px;width:${visualWidth}px"></canvas>${Object.values(c.keyframes).flatMap(keys=>keys?.filter(k=>k.time>=c.sourceIn&&k.time<=c.sourceOut).map(k=>`<span class="clip-key" style="left:${scale.toX(c.start+(k.time-c.sourceIn)/c.rate)-x}px"></span>`)??[]).join('')}<span class="clip-edge right" data-edge="right"></span></div>`;
    }).join('')}${p.proposals.filter(s=>s.before[0]?.trackId===t.id).map(s=>{const start=Math.min(...s.before.map(c=>c.start)),end=Math.max(...s.before.map(c=>c.start+duration(c)));return `<div class="suggestion-band" data-proposal="${s.id}" style="left:${scale.toX(start)}px;width:${scale.toX(end)-scale.toX(start)}px"><span>${s.changes.length} suggested · click to review</span></div>`;}).join('')}</div></div>`).join('')}<div class="playhead" style="left:${120+scale.toX(o.playhead)}px"></div>`;
  requestAnimationFrame(()=>host.querySelectorAll<HTMLCanvasElement>('[data-visual]').forEach(canvas=>{
    const c=p.clips.find(c=>c.id===canvas.dataset.visual)!,asset=p.assets.find(a=>a.id===c.assetId)!,x0=Number(canvas.dataset.x);canvas.width=Math.min(1800,Math.max(1,Math.ceil(parseFloat(canvas.style.width))));canvas.height=o.structure?56:30;const ctx=canvas.getContext('2d')!,pixelScale=parseFloat(canvas.style.width)/canvas.width;
    const source=(x:number)=>sourceAt(c,scale.toTime(x0+x*pixelScale));
    function paintAudio(){const e=media.envelopes.get(c.assetId),s=media.spectra.get(c.assetId);if(o.audioView==='none')return;
      if(o.audioView==='frequency'&&s){const image=ctx.createImageData(canvas.width,canvas.height);for(let x=0;x<canvas.width;x++){const column=Math.max(0,Math.min(s.columns-1,Math.floor(source(x)/s.step)));for(let y=0;y<canvas.height;y++){const bin=Math.min(s.bins-1,Math.floor((1-y/canvas.height)*s.bins)),v=s.data[column*s.bins+bin]/255,at=(y*canvas.width+x)*4;image.data[at]=20+230*v*v;image.data[at+1]=25+180*v;image.data[at+2]=55+75*v;image.data[at+3]=225;}}ctx.putImageData(image,0,0);return;}
      if(!e)return;ctx.strokeStyle='#c4ecd6';ctx.fillStyle='#a9d4bd';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<canvas.width;x+=o.audioView==='levels'?4:1){const t=source(x),index=Math.max(0,Math.min(e.rms.length-1,Math.floor(t/e.step))),amp=e.rms[index]*audioGain(c,c.start+(t-c.sourceIn)/c.rate),height=canvas.height*(o.audioView==='levels'?Math.max(0,Math.min(1,(20*Math.log10(Math.max(1e-6,amp))+60)/60)):Math.min(.48,amp*2));if(o.audioView==='levels')ctx.fillRect(x,canvas.height-height,2,height);else{ctx.moveTo(x,canvas.height/2-height);ctx.lineTo(x,canvas.height/2+height);}}ctx.stroke();}
    paintAudio();if(o.videoView==='filmstrip'&&asset.kind!=='audio'&&asset.thumbnail){const tiles=Math.min(8,Math.max(1,Math.ceil(canvas.width/100))),tileWidth=canvas.width/tiles;for(let i=0;i<tiles;i++){const draw=(url:string)=>{const image=new Image();image.onload=()=>{if(!canvas.isConnected)return;ctx.globalAlpha=.55;ctx.drawImage(image,i*tileWidth,0,tileWidth,canvas.height);ctx.globalAlpha=1;paintAudio();};image.src=url;};draw(asset.thumbnail);if(asset.kind==='video'&&media.files.has(asset.id))void media.thumbnail(asset.id,Math.max(c.sourceIn,Math.min(c.sourceOut-.001,source((i+.5)*tileWidth))),()=>canvas.isConnected).then(url=>{if(url)draw(url);}).catch(()=>{});}}
  }));
}
