import {type Project,type Asset,copy,uid} from './model';
import {validRegion,type VisualRegion} from './composition';
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);
export function regionEditor(h:{project:()=>Project;save:(p:Project)=>void;urls:Map<string,string>;dialog:(title:string,body:string,wide?:boolean)=>HTMLDialogElement;add:(region:VisualRegion)=>void;message:(s:string)=>void}){
  const assets=h.project().assets.filter(a=>a.kind!=='audio'&&h.urls.has(a.id));if(!assets.length){h.message('Import or relink video or an image first.');return;}
  const d=h.dialog('Visual source regions','',true),body=d.querySelector<HTMLElement>('.dialog-body')!;let asset=assets[0],current:VisualRegion={id:uid(),name:'Region',assetId:asset.id,left:.1,top:.1,right:.9,bottom:.9},cancelDrag:(()=>void)|undefined;
  function render(){cancelDrag?.();const width=Math.min(650,innerWidth*.65,innerHeight*.45*asset.width/asset.height);body.innerHTML=`<div class="field"><label>Source</label><select id="region-source">${assets.map(a=>`<option value="${esc(a.id)}"${a.id===asset.id?' selected':''}>${esc(a.name)}</option>`).join('')}</select></div><p>Drag a rectangle over the frame. Video controls below let you choose the frame. Regions share the original file.</p><div class="visual-region-stage" style="position:relative;width:${width}px;aspect-ratio:${asset.width}/${asset.height};max-width:100%">${asset.kind==='video'?`<video id="region-source-video" src="${esc(h.urls.get(asset.id))}" muted playsinline style="position:absolute;width:100%;height:100%"></video>`:`<img src="${esc(h.urls.get(asset.id))}" style="position:absolute;width:100%;height:100%" alt="Source">`}<canvas id="region-drawing" width="1000" height="${Math.round(1000*asset.height/asset.width)}" style="position:absolute;width:100%;height:100%;touch-action:none"></canvas></div>${asset.kind==='video'?'<input id="region-frame" type="range" min="0" max="1000" value="0" aria-label="Choose source frame" style="width:100%">':''}<div class="field"><label>Region name</label><input id="visual-region-name" value="${esc(current.name)}"></div><div class="row" id="region-saved-list">${(h.project().visualRegions??[]).filter(r=>r.assetId===asset.id).map(r=>`<button data-region-load="${esc(r.id)}">${esc(r.name)}</button>`).join('')}</div>`;
    const canvas=body.querySelector<HTMLCanvasElement>('#region-drawing')!,ctx=canvas.getContext('2d')!;const paint=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#0006';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.clearRect(current.left*canvas.width,current.top*canvas.height,(current.right-current.left)*canvas.width,(current.bottom-current.top)*canvas.height);ctx.strokeStyle='#bcf3cb';ctx.lineWidth=4;ctx.strokeRect(current.left*canvas.width,current.top*canvas.height,(current.right-current.left)*canvas.width,(current.bottom-current.top)*canvas.height);};paint();
    canvas.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const rect=canvas.getBoundingClientRect(),point=(ev:PointerEvent)=>({x:Math.max(0,Math.min(1,(ev.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(ev.clientY-rect.top)/rect.height))}),start=point(e),old=copy(current);const move=(ev:PointerEvent)=>{if(ev.pointerId!==e.pointerId)return;const end=point(ev);current={...current,left:Math.min(start.x,end.x),right:Math.max(start.x,end.x),top:Math.min(start.y,end.y),bottom:Math.max(start.y,end.y)};paint();};const clean=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',cancel);cancelDrag=undefined;};const up=(ev:PointerEvent)=>{if(ev.pointerId!==e.pointerId)return;clean();if(!validRegion(current))current=old;paint();};const cancel=()=>{clean();current=old;paint();};cancelDrag=cancel;window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',cancel);};
    body.querySelector<HTMLSelectElement>('#region-source')!.onchange=e=>{asset=assets.find(a=>a.id===(e.target as HTMLSelectElement).value)!;current={id:uid(),name:'Region',assetId:asset.id,left:.1,top:.1,right:.9,bottom:.9};render();};const slider=body.querySelector<HTMLInputElement>('#region-frame');if(slider)slider.oninput=()=>{const video=body.querySelector<HTMLVideoElement>('#region-source-video')!;if(video.readyState>0)video.currentTime=Math.max(0,Number(slider.value)/1000*(asset.duration-.01));};body.querySelectorAll<HTMLButtonElement>('[data-region-load]').forEach(b=>b.onclick=()=>{current=copy(h.project().visualRegions!.find(r=>r.id===b.dataset.regionLoad)!);render();});
  }
  const actions=d.querySelector('.dialog-actions')!,save=()=>{if(!validRegion(current)){h.message('Draw a region at least 1% of the source size.');return false;}current.name=body.querySelector<HTMLInputElement>('#visual-region-name')!.value.trim()||'Region';const p=copy(h.project());p.visualRegions=[...(p.visualRegions??[]).filter(r=>r.id!==current.id),copy(current)];h.save(p);return true;};for(const [label,fn]of [['Save region',()=>{if(save())render();}],['Add region to timeline',()=>{if(save())h.add(copy(current));}],['Delete region',()=>{const p=copy(h.project());p.visualRegions=p.visualRegions?.filter(r=>r.id!==current.id);h.save(p);current.id=uid();render();}],['Done',()=>d.close()]] as const){const b=document.createElement('button');b.textContent=label;b.onclick=fn;actions.append(b);}render();d.addEventListener('close',()=>{cancelDrag?.();body.querySelector('video')?.remove();},{once:true});
}
