  dispose(){this.cancelGesture?.();this.host.removeEventListener('click',this.click);this.host.removeEventListener('pointerdown',this.pointerdown);this.host.removeEventListener('keydown',this.keydown);this.host.removeEventListener('wheel',this.wheel);this.host.removeEventListener('contextmenu',this.contextmenu);this.host.removeEventListener('dragover',this.dragover);this.host.removeEventListener('drop',this.drop);this.host.removeEventListener('change',this.variantChange);}
