  $('.dialog-actions',d).append(button('Unlink markers',()=>{const next=copy(project);next.regions=next.regions?.filter(r=>r.id!==id);commit(next);d.close();}),button('Save',()=>{if(saveRegion())d.close();}),button('Run edit…',()=>{const workflow=$<HTMLSelectElement>('#region-workflow',d).value;if(workflow&&saveRegion()){d.close();void runOptions(workflow,id);}},'primary'));
