import {copy,resolveReference,setPolicy,referenceDiff,cloneDefinition,walkSteps,normalizeOverrides,type Step,type Definition,type Reference,type OpStep} from '../../model';
import {operationFields} from '../../builder';
import {operationLabels,workflowBlock} from '../workflows';
import {esc} from './canvas';
export interface WorkflowSettingsHooks {library:()=>Definition[];saveDefinition:(d:Definition)=>void;source:(id:string)=>void;branch:(which:'then'|'otherwise')=>void;confirm:(body:string)=>Promise<'keep'|'unlock'|'clone'>}
export function workflowSettings(host:HTMLElement,inputStep:Step,change:(step:Step)=>void,h:WorkflowSettingsHooks,message:(text:string)=>void){
  const step=inputStep.type==='reference'?normalizeOverrides(inputStep,h.library()):inputStep;
  const fields=(op:OpStep,ref?:Reference)=>operationFields[op.operation].map(f=>{const key=`${op.id}:${f.key}`,kept=ref&&key in ref.overrides,value=op.params[f.key]??f.default;return `<label class="node-field"><span>${esc(f.label)}</span>${f.options?`<select data-value="${ref?key:f.key}">${f.options.map(([v,label])=>`<option value="${v}"${v===value?' selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input data-value="${ref?key:f.key}" type="number" step="any" min="${f.min??-1e6}" max="${f.max??1e6}" value="${esc(value)}" required>`}${f.hint?`<small>${esc(f.hint)}</small>`:''}</label>${kept?`<button data-follow="${esc(key)}" class="small">Locked locally · Follow value</button>`:''}`;}).join('');
  let content='';let resolved:Definition|undefined;
  if(step.type==='operation')content=`<label class="node-field"><span>${['detectQuiet','quiet'].includes(step.operation)?'Signal channel':'Action type'}</span><select data-operation>${(['detectQuiet','quiet'].includes(step.operation)?['detectQuiet','quiet']:['shorten','speed','normalize','check']).map(op=>`<option value="${op}"${op===step.operation?' selected':''}>${operationLabels[op as keyof typeof operationLabels]}</option>`).join('')}</select></label>${fields(step)}`;
  if(step.type==='condition')content=`<h3>Decide</h3><label class="node-field"><span>When</span><select data-test>${[['matches','Content matches the preceding detector'],['duration','Duration'],['loudness','Loudness'],['audio','Audio is present']].map(([v,l])=>`<option value="${v}"${v===step.test?' selected':''}>${l}</option>`).join('')}</select></label>${['duration','loudness'].includes(step.test)?`<label class="node-field"><span>Comparison</span><select data-param="compare">${[['gt','Greater than'],['gte','At least'],['lt','Less than'],['lte','At most']].map(([v,l])=>`<option value="${v}"${v===(step.params.compare??'gt')?' selected':''}>${l}</option>`).join('')}</select></label><label class="node-field"><span>${step.test==='duration'?'Seconds':'Loudness (LUFS)'}</span><input type="number" step="any" data-param="value" value="${step.params.value??20}"></label>`:''}<label class="node-check"><input type="checkbox" data-invert${step.params.invert?' checked':''}> Reverse condition</label><button class="branch-open" data-branch="then">Then · ${step.then.length} nodes →</button><button class="branch-open" data-branch="otherwise">Otherwise · ${step.otherwise.length} nodes →</button>`;
  if(step.type==='reference'){try{resolved=resolveReference(step,h.library());content=`<h3>${esc(resolved.name)}</h3><button data-source>Open source pipeline →</button><button data-clone>Clone this setup</button><label class="node-field"><span>Updates</span><select data-policy>${[['follow','Linked · follow updates'],['definition','Frozen definition · one layer'],['bake','Baked · entire subtree']].map(([v,l])=>`<option value="${v}"${step.policy===v?' selected':''}>${l}</option>`).join('')}</select></label><details><summary>Parameters for this use</summary>${walkSteps(resolved.steps).filter((s):s is OpStep=>s.type==='operation').map(op=>`<h4>${operationLabels[op.operation]}</h4>${fields(op,step)}`).join('')}</details>`;}catch(e){content=`<p>${esc((e as Error).message)}</p>`;}}
  host.innerHTML=content+`<label class="node-field"><span>Implementation</span><select data-mode>${[['inherit','Use surrounding setting'],['automatic','Automatic'],['suggested','Suggest on timeline']].map(([v,l])=>`<option value="${v}"${v===step.mode?' selected':''}>${l}</option>`).join('')}</select></label>`;
  function cloneSetup(){if(!resolved)return;const d=cloneDefinition(resolved,h.library(),`${resolved.name} copy`);h.saveDefinition(d);change({...copy(step as Reference),definitionId:d.id,policy:'follow',frozen:undefined,unbaked:undefined,overrides:{}});}
  async function release(next:Reference){const diff=referenceDiff(step as Reference,next,h.library());if(diff.length){const answer=await h.confirm(`<p>Following current settings changes this setup:</p><table class="diff-table">${diff.map(d=>`<tr><td>${esc(d.path)}</td><td>${esc(d.before)}</td><td>→ ${esc(d.after)}</td></tr>`).join('')}</table>`);if(answer==='clone'){cloneSetup();return;}if(answer!=='unlock'){const field=host.querySelector<HTMLSelectElement>('[data-policy]');if(field)field.value=(step as Reference).policy;return;}}change(next);}
  host.onchange=e=>{void(async()=>{const el=e.target as HTMLInputElement|HTMLSelectElement;if(el.hasAttribute('data-node-alias'))return;if(el instanceof HTMLInputElement&&!el.reportValidity())return;const next=copy(step);if(el.dataset.value){if(next.type==='operation')next.params[el.dataset.value]=el instanceof HTMLSelectElement?el.value:Number(el.value);if(next.type==='reference')next.overrides[el.dataset.value]=el instanceof HTMLSelectElement?el.value:Number(el.value);}
    if(el.hasAttribute('data-operation')){const s=workflowBlock('workflow-'+el.value,next.id).params.legacyStep as Step;s.mode=next.mode;change(s);return;}if(el.hasAttribute('data-mode'))next.mode=el.value as Step['mode'];if(next.type==='condition'){if(el.hasAttribute('data-test'))next.test=el.value as typeof next.test;if(el.dataset.param)next.params[el.dataset.param]=el instanceof HTMLSelectElement?el.value:Number(el.value);if(el.hasAttribute('data-invert'))next.params.invert=(el as HTMLInputElement).checked;}
    if(el.hasAttribute('data-policy')&&next.type==='reference'){const changed=setPolicy(next,el.value as Reference['policy'],h.library());if((next.policy==='bake'&&changed.policy!=='bake')||(next.policy==='definition'&&changed.policy==='follow'))await release(changed);else change(changed);return;}change(next);
  })().catch(e=>message(e.message));};
  host.onclick=e=>{const el=(e.target as Element).closest<HTMLElement>('button');if(!el)return;e.stopPropagation();if(el.dataset.branch)h.branch(el.dataset.branch as 'then');if(el.hasAttribute('data-source')&&resolved)h.source(resolved.id);if(el.hasAttribute('data-clone'))cloneSetup();if(el.dataset.follow&&step.type==='reference'){const next=copy(step);delete next.overrides[el.dataset.follow];void release(next).catch(e=>message(e.message));}};
}
