import {copy,uid,latest,currentDefinitions,reference,resolveReference,setPolicy,referenceDiff,cloneDefinition,compile,normalizeOverrides,walkSteps,type Definition,type Step,type OpStep,type Reference,type ConditionStep,type Mode,type Operation} from './model';
interface Choice {id:string;label:string;kind?:string;}
export interface BuilderHooks {library:()=>Definition[];dialog:(title:string,body:string,wide?:boolean)=>HTMLDialogElement;choose:(title:string,body:string,options:Choice[],wide?:boolean)=>Promise<{id:string;values:Record<string,string>}>;name:(title:string,value:string)=>Promise<string|undefined>;save:(d:Definition)=>void;clone:(d:Definition)=>void;toast:(message:string,error?:boolean)=>void;}
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
interface Field {key:string;label:string;default:number|string;min?:number;max?:number;step?:number;options?:[string,string][];hint?:string;}
export const operationNames:Record<Operation,string>={detectQuiet:'Find quiet sections',shorten:'Shorten sections',speed:'Change playback speed',normalize:'Adjust audio loudness',check:'Check the result',quiet:'Find and shorten quiet · legacy'};
const detectionFields:Field[]=[{key:'threshold',label:'Audio quieter than (dBFS)',default:-40,min:-90,max:0,hint:'Lower values mean only very quiet audio will match.'},{key:'minQuiet',label:'Lasting at least (seconds)',default:2,min:.02,max:600,step:.1},{key:'burstDuration',label:'Ignore sound bursts up to (seconds)',default:1,min:0,max:10,step:.1},{key:'burstCeiling',label:'Only if those bursts stay below (dBFS)',default:-25,min:-90,max:0}];
const targets:[string,string][]=[['quiet','Sections found by the last detector'],['all','All content reaching this step']];
export const operationFields:Record<Operation,Field[]>={detectQuiet:detectionFields,shorten:[{key:'retain',label:'Keep up to (seconds per section)',default:20,min:0,max:600,step:.1,hint:'Keep the beginning and end; remove the middle. Time is measured at this step.'},{key:'target',label:'Apply to',default:'quiet',options:targets}],quiet:[...detectionFields,{key:'retain',label:'Keep up to (seconds)',default:20,min:0,max:600,step:.1}],speed:[{key:'rate',label:'Multiply speed by',default:1.3,min:.1,max:8,step:.05},{key:'target',label:'Apply to',default:'quiet',options:targets}],normalize:[{key:'target',label:'Target loudness (LUFS)',default:-16,min:-40,max:-8},{key:'maxBoost',label:'Maximum boost (dB)',default:12,min:0,max:24},{key:'peak',label:'Sample peak guard (dBFS)',default:-1,min:-12,max:0,step:.1,hint:'Loudness estimate; oversampled true-peak limiting is planned.'},{key:'affected',label:'Apply to',default:'all',options:targets}],check:[{key:'minDuration',label:'No section shorter than (seconds)',default:.1,min:0,max:10,step:.01},{key:'maxRate',label:'No playback faster than',default:4,min:.1,max:8,step:.1}]};
const modeOptions=(mode:Mode)=>[['inherit','Use the surrounding workflow setting'],['suggested','Suggest changes in the timeline'],['automatic','Apply changes automatically']].map(([v,l])=>`<option value="${v}"${mode===v?' selected':''}>${l}</option>`).join('');
const field=(f:Field,v:unknown,attr:string)=>`<div class="field"><label>${esc(f.label)}</label>${f.options?`<select ${attr}>${f.options.map(([value,label])=>`<option value="${value}"${v===value?' selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input ${attr} type="number" min="${f.min??-1e6}" max="${f.max??1e6}" step="${f.step??1}" value="${esc(v)}">`}${f.hint?`<span class="hint">${esc(f.hint)}</span>`:''}</div>`;
function makeStep(choice:string):Step {if(choice==='condition')return {id:uid(),type:'condition',test:'matches',params:{},mode:'inherit',then:[],otherwise:[]};if(choice.startsWith('ref:'))return reference(choice.slice(4));const op=choice as Operation;return {id:uid(),type:'operation',operation:op,mode:'inherit',params:Object.fromEntries(operationFields[op].map(f=>[f.key,f.default]))};}
function diffTable(diff:ReturnType<typeof referenceDiff>){return `<table class="diff-table"><thead><tr><th>Setting</th><th>Active setup</th><th>After unlocking</th></tr></thead><tbody>${diff.map(d=>`<tr><td>${esc(d.path)}</td><td>${esc(d.before??'—')}</td><td>${esc(d.after??'—')}</td></tr>`).join('')}</tbody></table>`;}
export function openWorkflowBuilder(h:BuilderHooks,original?:Definition,kind:'quick'|'preset'='preset'):HTMLDialogElement {
  const d:Definition=original?copy(original):{id:uid(),version:0,name:kind==='quick'?'New Quick Edit':'New preset',description:'',kind,mode:kind==='quick'?'suggested':'inherit',initial:false,steps:[]};
  const dialog=h.dialog(original?`Edit ${d.name}`:`Create ${kind==='quick'?'Quick Edit':'preset'}`,'',true),body=dialog.querySelector<HTMLElement>('.dialog-body')!;
  const getList=(path:string):Step[]=>{let list=d.steps;const tokens=path?path.split('.'):[];for(let i=0;i<tokens.length;i+=2){const node=list[Number(tokens[i])];if(node?.type!=='condition')throw Error('This branch no longer exists.');list=tokens[i+1]==='then'?node.then:node.otherwise;}return list;};
  const locate=(path:string)=>{const parts=path.split('.'),index=Number(parts.pop());const list=getList(parts.join('.'));return {list,index,step:list[index]};};
  function controls(path:string){return `<span class="step-actions"><button class="ghost small" data-move="${path}|-1" title="Move step up">↑</button><button class="ghost small" data-move="${path}|1" title="Move step down">↓</button><button class="ghost small danger" data-remove="${path}" title="Remove step">×</button></span>`;}
  function addControls(path:string){return `<div class="workflow-add row"><select class="grow" data-palette="${path}" aria-label="Choose a workflow building block"><option value="">Add a building block…</option><optgroup label="Find conditions"><option value="detectQuiet">Find quiet sections</option></optgroup><optgroup label="Decide what happens"><option value="condition">If… then… otherwise…</option></optgroup><optgroup label="Edit actions"><option value="shorten">Shorten sections</option><option value="speed">Change speed</option><option value="normalize">Adjust loudness</option><option value="check">Check result</option></optgroup><optgroup label="Reuse a workflow">${currentDefinitions(h.library()).filter(c=>c.id!==d.id).map(c=>`<option value="ref:${c.id}">${esc(c.name)}</option>`).join('')}</optgroup></select><button class="small" data-add="${path}">+ Add</button></div>`;}
  function renderSteps(steps:Step[],parent=''):string{return steps.map((s,i)=>{const path=parent?`${parent}.${i}`:String(i);
    if(s.type==='operation'){const detector=s.operation==='detectQuiet';return `<div class="step-card workflow-step ${detector?'find-step':'action-step'}"><div class="step-title"><span><span class="block-type">${detector?'FIND':s.operation==='check'?'CHECK':'DO'}</span> <strong>${esc(operationNames[s.operation])}</strong></span>${controls(path)}</div><div class="step-fields">${operationFields[s.operation].map(f=>field(f,s.params[f.key]??f.default,`data-param="${path}|${f.key}"`)).join('')}</div>${detector?'<div class="tiny muted">Identifies matching regions. This step does not change the media.</div>':`<details class="workflow-details"><summary>How to apply this action</summary><select data-step-mode="${path}">${modeOptions(s.mode)}</select></details>`}</div>`;}
    if(s.type==='condition'){const test=s.test;return `<div class="step-card workflow-step condition-step"><div class="step-title"><span><span class="block-type">IF</span> <strong>Choose what happens</strong></span>${controls(path)}</div><div class="field"><label>When this is true</label><select data-test="${path}"><option value="matches"${test==='matches'?' selected':''}>This section matches the last detector</option><option value="duration"${test==='duration'?' selected':''}>This section has a certain duration</option><option value="loudness"${test==='loudness'?' selected':''}>This section has a certain loudness</option><option value="audio"${test==='audio'?' selected':''}>The clip has an audio track</option></select></div>${test==='duration'||test==='loudness'?`<div class="step-fields">${field({key:'compare',label:'Comparison',default:test==='duration'?'gt':'lt',options:[['gt','is greater than'],['gte','is at least'],['lt','is less than'],['lte','is at most']]},s.params.compare??(test==='duration'?'gt':'lt'),`data-param="${path}|compare"`)}${field({key:'value',label:test==='duration'?'Seconds at this step':'Loudness (LUFS)',default:test==='duration'?20:-20,step:.1},s.params.value??(test==='duration'?20:-20),`data-param="${path}|value"`)}</div>`:''}<label class="row tiny muted"><input type="checkbox" data-invert="${path}"${s.params.invert?' checked':''}> Reverse the condition (when it is not true)</label><div class="logic-branch"><div class="branch-label">THEN</div>${renderSteps(s.then,`${path}.then`)}${!s.then.length?'<p class="branch-empty">Choose an action for matching sections.</p>':''}${addControls(`${path}.then`)}</div><div class="logic-branch otherwise"><div class="branch-label">OTHERWISE</div>${renderSteps(s.otherwise,`${path}.otherwise`)}${!s.otherwise.length?'<p class="branch-empty">Keep the section unchanged.</p>':''}${addControls(`${path}.otherwise`)}</div></div>`;}
    const ref=normalizeOverrides(s,h.library());s.overrides=ref.overrides;let child:Definition;try{child=resolveReference(s,h.library());}catch(error){return `<div class="step-card">${esc((error as Error).message)}${controls(path)}</div>`;}
    return `<div class="step-card workflow-step reuse-step"><div class="step-title"><span><span class="block-type">REUSE</span> <strong>${esc(child.name)}</strong></span>${controls(path)}</div><div class="row between"><span class="tiny muted">${child.kind==='quick'?'QUICK EDIT':'PRESET'} · v${child.version}</span><button class="small ghost" data-clone-ref="${path}">Clone setup</button></div><select class="ref-policy" data-policy="${path}"><option value="follow"${s.policy==='follow'?' selected':''}>Follow updates</option><option value="definition"${s.policy==='definition'?' selected':''}>Lock definition · one layer</option><option value="bake"${s.policy==='bake'?' selected':''}>Bake · recursively lock subtree</option></select><details class="workflow-details"><summary>Adjust this use of the workflow</summary>${walkSteps(child.steps).filter((n):n is OpStep=>n.type==='operation').map(op=>`<div class="section-label">${esc(operationNames[op.operation])}</div><div class="step-fields">${operationFields[op.operation].map(f=>{const key=`${op.id}:${f.key}`,kept=key in s.overrides;return `<div>${field(f,op.params[f.key]??f.default,`data-ref-param="${path}|${key}"`)}<div class="row tiny">${kept?`<span class="kept">Kept locally</span><button class="ghost small" data-release="${path}|${key}">Follow value</button>`:'<span class="muted">Following definition</span>'}</div></div>`;}).join('')}</div>`).join('')}<div class="field"><label>Application override</label><select data-step-mode="${path}">${modeOptions(s.mode)}</select></div></details><button class="ghost small" data-edit-source="${child.id}">Edit shared source definition</button></div>`;
  }).join('');}
  function render(){body.innerHTML=`<div class="field-pair"><div class="field"><label>Name</label><input data-def="name" value="${esc(d.name)}" maxlength="100"></div><div class="field"><label>Default application</label><select data-def="mode">${modeOptions(d.mode)}</select></div></div><div class="field"><label>Description</label><input data-def="description" value="${esc(d.description)}"></div>${d.kind==='preset'?`<label class="row tiny muted"><input data-def="initial" type="checkbox"${d.initial?' checked':''}> Offer as an initial preset when a clip is added</label>`:''}<div class="workflow-intro"><strong>Find → Decide → Edit</strong><p>Build the workflow from small steps. Find regions, choose conditions, then decide what to change. Save the result as a Quick Edit or reusable preset.</p></div><div class="workflow-tree">${renderSteps(d.steps)}${!d.steps.length?'<div class="callout">Start with Find quiet sections, an action, or another saved workflow.</div>':''}${addControls('')}</div>`;}
  async function cloneRef(path:string){const located=locate(path),ref=located.step as Reference,current=resolveReference(ref,h.library()),name=await h.name('Clone current setup',`${current.name} copy`);if(!name)return;const clone=cloneDefinition(current,h.library(),name);h.clone(clone);located.list[located.index]={...reference(clone.id),mode:ref.mode};h.toast('Clone saved with pinned descendants. This step now uses the clone.');}
  body.addEventListener('change',e=>{void(async()=>{const el=e.target as HTMLInputElement|HTMLSelectElement;
    if(el.dataset.def){const k=el.dataset.def;if(k==='initial')d.initial=(el as HTMLInputElement).checked;else (d as any)[k]=el.value;}
    if(el.dataset.param){const[path,key]=el.dataset.param.split('|'),s=locate(path).step;if(s.type!=='reference')s.params[key]=el instanceof HTMLSelectElement?el.value:Number(el.value);}
    if(el.dataset.test){const s=locate(el.dataset.test).step as ConditionStep;s.test=el.value as ConditionStep['test'];s.params={value:s.test==='duration'?20:-20,compare:s.test==='duration'?'gt':'lt'};render();}
    if(el.dataset.invert)(locate(el.dataset.invert).step as ConditionStep).params.invert=(el as HTMLInputElement).checked;
    if(el.dataset.stepMode)locate(el.dataset.stepMode).step.mode=el.value as Mode;
    if(el.dataset.refParam){const[path,key]=el.dataset.refParam.split('|');(locate(path).step as Reference).overrides[key]=el instanceof HTMLSelectElement?el.value:Number(el.value);render();}
    if(el.dataset.policy){const path=el.dataset.policy,{list,index,step}=locate(path),old=step as Reference,next=setPolicy(old,el.value as Reference['policy'],h.library());if((old.policy==='bake'&&next.policy!=='bake')||(old.policy==='definition'&&next.policy==='follow')){const diff=referenceDiff(old,next,h.library());if(diff.length){const result=await h.choose('Use current definition settings?',`<p>Unlocking adopts the effective current settings. Separately kept parameters remain protected.</p>${diffTable(diff)}`,[{id:'keep',label:'Keep locked'},{id:'clone',label:'Clone current setup…'},{id:'unlock',label:'Unlock and use current settings',kind:'primary'}],true);if(result.id==='clone'){await cloneRef(path);render();return;}if(result.id!=='unlock'){render();return;}}}list[index]=next;render();}
  })().catch(error=>{h.toast((error as Error).message,true);render();});});
  body.addEventListener('click',e=>{void(async()=>{const el=(e.target as HTMLElement).closest<HTMLElement>('button');if(!el)return;
    if(el.dataset.add!==undefined){const path=el.dataset.add,select=Array.from(body.querySelectorAll<HTMLSelectElement>('[data-palette]')).find(s=>s.dataset.palette===path)!;if(select.value){getList(path).push(makeStep(select.value));render();}}
    if(el.dataset.remove){const{list,index}=locate(el.dataset.remove);list.splice(index,1);render();}
    if(el.dataset.move){const[path,amount]=el.dataset.move.split('|'),{list,index}=locate(path),to=index+Number(amount);if(to>=0&&to<list.length){[list[index],list[to]]=[list[to],list[index]];render();}}
    if(el.dataset.cloneRef){await cloneRef(el.dataset.cloneRef);render();}
    if(el.dataset.release){const[path,key]=el.dataset.release.split('|'),{list,index,step}=locate(path),old=step as Reference,next=copy(old);delete next.overrides[key];const diff=referenceDiff(old,next,h.library());if(diff.length){const result=await h.choose('Follow the definition’s value?',`<p>This parameter will use its inherited value.</p>${diffTable(diff)}`,[{id:'keep',label:'Keep local value'},{id:'clone',label:'Clone current setup…'},{id:'release',label:'Follow value',kind:'primary'}]);if(result.id==='clone'){await cloneRef(path);render();return;}if(result.id!=='release')return;}list[index]=next;render();}
    if(el.dataset.editSource)openWorkflowBuilder(h,latest(h.library(),el.dataset.editSource)).addEventListener('close',render,{once:true});
  })().catch(error=>h.toast((error as Error).message,true));});
  const actions=dialog.querySelector('.dialog-actions')!;for(const [label,fn,primary]of [['Cancel',()=>dialog.close(),false],['Save workflow',()=>{try{for(const field of body.querySelectorAll<HTMLInputElement>('input[type=number]'))if(!field.reportValidity())return;const input=body.querySelector<HTMLInputElement>('[data-def=name]')!;d.name=input.value.trim();if(!d.name||!d.steps.length)throw Error('Give the workflow a name and at least one step.');d.version=original?latest(h.library(),d.id).version+1:1;const library=[...h.library(),d];for(const def of currentDefinitions(library))compile(def,library);h.save(copy(d));dialog.close();}catch(error){h.toast((error as Error).message,true);}},true]]as const){const b=document.createElement('button');b.textContent=label;if(primary)b.className='primary';b.onclick=fn;actions.append(b);}render();return dialog;
}
